const existTags = card && Array.isArray(card.tagIds) ? card.tagIds : [];
const tagIds = Array.from(new Set([...existTags, cfg.ia_card_tag_id].filter(Boolean)));
const title = (card && card.title) || cu.nome_paciente || 'Paciente';

